var paths=new[]{"Assets/Maps/Buildings/Doors/Prefabs/Door_Single_Metal.prefab","Assets/Maps/Buildings/Walls/Prefabs/Inside/Room_Wall_Door.prefab"};return paths.Select(p=>{var g=UnityEditor.AssetDatabase.LoadAssetAtPath<GameObject>(p);return new{path=p,meshes=g.GetComponentsInChildren<MeshFilter>(true).Select(m=>new{name=m.name,size=m.sharedMesh?m.sharedMesh.bounds.size.ToString("F4"):null,scale=m.transform.lossyScale.ToString("F4")}).ToArray()};}).ToArray();
